icon-button:
import { Play } from 'lucide-react'
import {
  IconButton,
  type IconButtonAnimation,
  type IconButtonDirection,
  type IconButtonSize,
  type IconButtonVariant,
} from 'splatoon-ui/icon-button'

type IconButtonExampleProps = {
  variant: IconButtonVariant
  size: IconButtonSize
  animation: IconButtonAnimation
  direction: IconButtonDirection
}

export function IconButtonExample({
  variant,
  size,
  animation,
  direction,
}: IconButtonExampleProps) {
  return (
    <div className="flex flex-wrap items-center justify-center gap-4">
      <IconButton
        aria-label={`Move ${direction}`}
        variant={variant}
        size={size}
        animation={animation}
        direction={direction}
      />
      <IconButton
        aria-label="Play"
        variant={variant}
        size={size}
        animation={animation}
        icon={<Play className="h-[calc(var(--size)*0.42)] w-[calc(var(--size)*0.42)]" />}
      />
    </div>
  )
}

